USE customer_behavior;
SELECT * FROM customer;

-- 1. Revenue Analysis - Compared total revenue generated by male and female customers.
select gender, sum(purchase_amount) as total_revenue
from customer
group by gender;


-- 2. Discount & Spending Analysis — Identified discount users whose purchase amounts were at or above the overall average.
select customer_id, purchase_amount
from customer
where discount_applied = 'Yes'
and purchase_amount >= (select avg(purchase_amount * 1.0) from customer);

-- purchase_amount tam sayý (int) olduðu için AVG(purchase_amount) sonucu 59 döner (59.76 deðil).
-- * 1.0 ile gerçek ortalama (59.76) kullanýlýr: sonuç 863 yerine doðru deðer olan 839 satýr olur.


-- 3. Product Rating Analysis — Ranked the top 5 products by average review rating.
SELECT TOP 5
    item_purchased,
    CAST(AVG(review_rating) AS DECIMAL(4,2)) AS [Average Product Rating]
FROM customer
GROUP BY item_purchased
ORDER BY AVG(review_rating) DESC;


-- 4. Shipping Analysis — Compared average purchase amounts for Standard and Express shipping.
select shipping_type,
CAST(AVG(purchase_amount * 1.0) AS DECIMAL(10,2)) as "average purchase amount"
from customer
where shipping_type in ('Standard','Express')
group by shipping_type;


-- 5. Subscription Analysis — Compared customer counts, average spending, and total revenue between subscribers and non-subscribers.
SELECT
    subscription_status,
    COUNT(customer_id) AS total_customers,
    CAST(AVG(purchase_amount * 1.0) AS DECIMAL(10,2)) AS avg_spend,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue DESC, avg_spend DESC;


-- * 1.0: Ondalýklý hesaplama yapýlmasýný saðlar.
-- CAST: Sonucu istenen veri tipine dönüþtürür.
-- DECIMAL(10,2): Sonucu virgülden sonra 2 basamaklý gösterir.


-- 6. Discount Dependency Analysis — Identified the top 5 products by percentage of purchases with discounts applied.
SELECT TOP 5
    item_purchased,
    CAST(
        ROUND(100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) / COUNT(*), 2) AS DECIMAL(10,2)
    ) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC, item_purchased;

-- item_purchased: Oranlar eþit çýkarsa ürünleri alfabetik sýralar, böylece sonuç her çalýþtýrmada ayný olur.


-- 7. Customer Segmentation — Classified customers into New, Returning, and Loyal segments based on previous purchases.
with customer_type as (
SELECT customer_id, previous_purchases,
CASE
    WHEN previous_purchases = 1 THEN 'New'
    WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
    ELSE 'Loyal'
    END AS customer_segment
FROM customer)
select customer_segment,count(*) AS [Number of Customers]
from customer_type
group by customer_segment;

/*WITH, sorgu boyunca kullanabileceðin geçici bir sonuç kümesi oluþturur. Bu yapýya CTE denir.
Gerçek bir tablo oluþturmaz; sorgunun okunmasýný ve düzenlenmesini kolaylaþtýrýr.*/


-- 8. Product Popularity Analysis — Identified the top 3 most purchased products within each category.
-- Her kategoride en çok satýn alýnan ilk 3 ürünü bulur.
-- WITH: Geçici bir sonuç kümesi (CTE) oluþturur.
-- RANK(): Ürünlere sýra numarasý verir; eþit satýþ sayýsýna sahip ürünlere ayný sýrayý verir.
--         (ROW_NUMBER() eþitlikte birini rastgele öne alýrdý: Belt ve Sunglasses ikisi de 161 sipariþ.)
-- PARTITION BY: Sýralamayý her kategori için yeniden baþlatýr.
-- ORDER BY COUNT(...) DESC: En çok satýlan ürünü ilk sýraya koyar.

WITH item_counts AS (
    SELECT
        category,
        item_purchased,
        COUNT(customer_id) AS total_orders,
        RANK() OVER (
            PARTITION BY category
            ORDER BY COUNT(customer_id) DESC
        ) AS item_rank
    FROM customer
    GROUP BY category, item_purchased
)
SELECT
    item_rank,
    category,
    item_purchased,
    total_orders
FROM item_counts
WHERE item_rank <= 3
ORDER BY category, item_rank, item_purchased;


-- 9. Repeat Buyer Analysis — Compared subscription status among customers with more than 5 previous purchases.
SELECT subscription_status,
       COUNT(customer_id) AS repeat_buyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;

-- 9b. 5'ten fazla alýþveriþ yapanlar daha çok abone oluyor mu? Abonelik oranlarýný karþýlaþtýrýr.
SELECT
    CASE WHEN previous_purchases > 5 THEN 'More than 5' ELSE '5 or fewer' END AS buyer_type,
    COUNT(*) AS total_customers,
    CAST(100.0 * SUM(CASE WHEN subscription_status = 'Yes' THEN 1 ELSE 0 END) / COUNT(*) AS DECIMAL(5,2)) AS subscription_rate
FROM customer
GROUP BY CASE WHEN previous_purchases > 5 THEN 'More than 5' ELSE '5 or fewer' END;


-- 10. Age Group Revenue Analysis — Compared total revenue across customer age groups.
SELECT
    age_group,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY age_group
ORDER BY total_revenue desc;


